import test from 'node:test';
import assert from 'node:assert/strict';
import {GEAR_CATALOG, normalizeMachineProfile, validateGear, normalizeAxialTransform, rotationIndex, snapIndex, machineReport, compatibleGears, symmetryDivisors, planeToAxialLocal, generatePreset, instancePlanes, transformPlane, normalizeTransform, validateWorkspace, prismSolid, nativeFacetInputs, makeNativeDocument, importNativeDocument, createHostBridge, nativeFacetPlane} from '../src/index.js';
import {cubeDocument} from './fixtures.mjs';
const near=(a,b,e=1e-9)=>assert.ok(Math.abs(a-b)<e,`${a} != ${b}`);
const workspace=(version=2)=>({kind:'opengemcutting-component-workspace',schemaVersion:version,state:{machine:normalizeMachineProfile(),stock:{polys:prismSolid(),convex:true},basePlanes:[],groups:[],draft:generatePreset(),transform:normalizeTransform(),editId:null}});
test('gear catalog distinguishes documented software presets from hardware',()=>{assert.deepEqual(GEAR_CATALOG.map(g=>g.teeth),[32,64,72,77,80,84,88,96,99,120,360]);assert.equal(GEAR_CATALOG.at(-1).kind,'software');assert.equal(GEAR_CATALOG.find(g=>g.teeth===88).kind,'documented');});
test('gear count must be a bounded positive integer',()=>{for(const n of [0,-96,96.5,NaN,Infinity,10001,'96'])assert.throws(()=>validateGear(n));for(const n of [1,3,4,77,96,288,10000])assert.equal(validateGear(n),n);});
test('machine profile cannot unlock axis, teeth-only mode or direction',()=>{for(const p of [{axis:'x'},{integerOnly:false},{direction:'cw'},{version:2}])assert.throws(()=>normalizeMachineProfile(p));assert.deepEqual(normalizeMachineProfile(),{version:1,axis:'z',integerOnly:true,direction:'ccw',teeth:96});});
for(const [key,axis] of [['translation',0],['translation',1],['rotation',0],['rotation',1]])test(`reject off-axis ${key}[${axis}], including tiny nonzero input`,()=>{for(const v of [.03,1e-12]){const t=normalizeTransform();t[key][axis]=v;assert.throws(()=>normalizeAxialTransform(t),/加工轴已锁定/);assert.throws(()=>instancePlanes(generatePreset(),t),/加工轴已锁定/);}});
for(const gear of GEAR_CATALOG.map(g=>g.teeth))test(`${gear} tooth rotation snaps, wraps and stays on fixed axis`,()=>{const angle=360/gear;const t=normalizeAxialTransform({rotation:[0,0,angle]},{teeth:gear});near(rotationIndex(t.rotation[2],gear),1);assert.equal(snapIndex(gear,gear),0);assert.equal(snapIndex(-1,gear),gear-1);assert.throws(()=>normalizeAxialTransform({rotation:[0,0,angle/3]},{teeth:gear}));near(normalizeAxialTransform({rotation:[0,0,angle*.9]},{teeth:gear,snap:true}).rotation[2],angle);});
test('96 integer index means 3.75 degrees, not integer degrees',()=>{near(normalizeAxialTransform({rotation:[0,0,3.75]},{teeth:96}).rotation[2],3.75);assert.throws(()=>normalizeAxialTransform({rotation:[0,0,1]},{teeth:96}));});
test('repeated snapped rotations have no drift after 100 full turns',()=>{let angle=0;for(let k=0;k<9600;k++)angle=normalizeAxialTransform({rotation:[0,0,angle+3.75]},{teeth:96}).rotation[2];near(angle,0);});
test('larger 120 and 360 gears are not supersets of 96',()=>{const p={n:[Math.cos(Math.PI/48),Math.sin(Math.PI/48),1],d:1};assert.ok(machineReport([p],96).exact);assert.ok(machineReport([p],192).exact);assert.ok(!machineReport([p],120).exact);assert.ok(!machineReport([p],360).exact);});
test('axis-normal table and culet do not create spurious index requirements',()=>{const planes=[{n:[0,0,1],d:1},{n:[0,0,-1],d:1}];for(const g of [77,96,99])assert.ok(machineReport(planes,g).exact);});
test('rim display cap is not a machining instruction',()=>{assert.equal(machineReport([{n:[1,.123,1],d:1,role:'interface'}],96).rows.length,0);});
test('uniform XY scaling and independent Z scaling preserve final index azimuths',()=>{const c=generatePreset();for(const scale of [[1.4,1.4,.7],[.7,.7,1.4],[1,1,2]])assert.ok(machineReport(instancePlanes(c,{translation:[0,0,.2],rotation:[0,0,3.75],scale}),96).exact);});
test('anisotropic XY scaling is exact geometry but not an integer-index design',()=>{const planes=instancePlanes(generatePreset(),{scale:[1.25,1,1]});const r=machineReport(planes,96);assert.equal(r.incompatible,28);assert.ok(r.maxErrorDeg>1.8 && r.maxErrorDeg<1.875);assert.throws(()=>nativeFacetInputs(generatePreset(),{scale:[1.25,1,1]},cubeDocument().stock),/非整数分度/);});
test('all plane normals are audited: N divides G is not sufficient for brilliant quarters',()=>{assert.ok(symmetryDivisors(72).includes(8));assert.ok(!machineReport(generatePreset().planes,72).exact);assert.ok(machineReport(generatePreset({params:{symmetry:9}}).planes,72).exact);});
test('mixed eight and nine crowns find exact custom288, not only the bigger gear',()=>{const planes=[...generatePreset().planes,...generatePreset({params:{symmetry:9}}).planes];const results=compatibleGears(planes,96);assert.ok(results.some(g=>g.teeth===288&&g.kind==='custom'));assert.ok(!results.some(g=>g.teeth===360));});
test('pullback world plane respects scale, rotation, Z translation',()=>{const t={translation:[0,0,.25],rotation:[0,0,7.5],scale:[1.2,.9,1.5]},p={id:'manual',n:[.5,.3,.9],d:.61};const local=planeToAxialLocal(p,t),world=transformPlane(local,t),target=transformPlane(p,{});world.n.forEach((v,i)=>near(v,target.n[i]));near(world.d,target.d);});
test('schema2 workspace round-trips the machine and snapped transforms',()=>{const w=workspace();w.state.machine.teeth=120;w.state.transform.rotation[2]=3;const s=validateWorkspace(JSON.parse(JSON.stringify(w)));assert.equal(s.machine.teeth,120);assert.equal(s.transform.rotation[2],3);});
test('workspace permits incompatible draft geometry for review, not forbidden placements',()=>{const w=workspace();w.state.draft=generatePreset({params:{symmetry:9}});assert.ok(validateWorkspace(w));w.state.transform.translation[0]=.1;assert.throws(()=>validateWorkspace(w),/加工轴已锁定/);});
test('legacy workspace migration retains legal shape, rejects off-axis without mutating input',()=>{const w=workspace(1);delete w.state.machine;assert.equal(validateWorkspace(w).machine.teeth,96);assert.equal(w.state.machine,undefined);w.state.transform.rotation[0]=15;const before=JSON.stringify(w);assert.throws(()=>validateWorkspace(w));assert.equal(JSON.stringify(w),before);});
test('workspace requires explicit v2 machine and rejects invalid group rotation',()=>{const w=workspace();delete w.state.machine;assert.throws(()=>validateWorkspace(w));w.state.machine=normalizeMachineProfile();w.state.groups=[{id:'a',component:generatePreset(),transform:{rotation:[0,0,1]}}];assert.throws(()=>validateWorkspace(w),/非整数分度/);});
test('native metadata cannot smuggle legacy lateral translation back into axis-locked studio',()=>{const stock={polys:prismSolid()},groups=[{id:'c',component:generatePreset(),transform:{translation:[0,0,.045]}}],doc=makeNativeDocument(stock,null,groups);doc.metadata.componentInstances[0].transform.translation[0]=.01;assert.throws(()=>importNativeDocument(doc),/加工轴已锁定/);});
test('retained native base CUT is validated before export',()=>{const base=cubeDocument();base.indexGear.teeth=120;assert.throws(()=>makeNativeDocument({polys:prismSolid()},base,[]),/indexGear/);});
test('host bridge axis and index rejection happens before dispatch',async()=>{let dispatches=0;const bridge=createHostBridge({domain:{resolveFacet:(f,{stock})=>({...f,plane:nativeFacetPlane(f,stock)}),createReplaceDocumentCommand:document=>({document})},getDocument:cubeDocument,getRevision:()=>1,canApply:()=>true,analyzeImpact:()=>({canApply:true}),dispatch:()=>dispatches++});for(const transform of [{translation:[.1,0,0]},{rotation:[0,0,1]},{scale:[1.2,1,1]}])await assert.rejects(()=>bridge.apply({component:generatePreset(),transform,instanceId:'bad'}));assert.equal(dispatches,0);});
